@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#cto-table'),form=document.querySelector('#cto-form'),action=document.querySelector('#cto-action-form');HRIS.bindForm(form,{prepare:b=>{b.dates=b.dates_text.split(/\n/).filter(Boolean).map(line=>{const [date,portion='WHOLE']=line.split(',').map(x=>x.trim().toUpperCase());return{date,portion}});delete b.dates_text},success:()=>table.table.load()});HRIS.bindForm(action,{success:()=>table.table.load()});table.addEventListener('table:action',({detail:{action:kind,row}})=>{if(kind==='details')HRIS.showDetails('CTO request',row);else{HRIS.fillForm(action,{});action.dataset.endpoint=`/cto/${row.id}/transition`;HRIS.openModal('cto-action')}})});</script>@endpush
